import FeatureGates from '@atlaskit/feature-gate-js-client/feature-gates';
import { addFeatureFlagAccessed } from '@atlaskit/react-ufo/feature-flags-accessed';
import { devOverrides, defaultBooleanExperimentsToTrue } from './dev-overrides-store';
export function expValInternal(experimentName, param, defaultValue, fireExperimentExposure) {
  // Dev-mode override (platform website dev panel, Gemini VR test harness).
  if (devOverrides.has(experimentName)) {
    // eslint-disable-next-line @typescript-eslint/consistent-type-assertions
    var overrideParams = devOverrides.get(experimentName);
    var overrideValue = overrideParams[param];
    if (overrideValue !== undefined) {
      addFeatureFlagAccessed("".concat(experimentName, ":").concat(param), overrideValue);
      // eslint-disable-next-line @typescript-eslint/consistent-type-assertions
      return overrideValue;
    }
    // eslint-disable-next-line @typescript-eslint/consistent-type-assertions
    return defaultValue;
  }
  if (process.env.NODE_ENV !== 'production' && defaultBooleanExperimentsToTrue && param === 'isEnabled' && defaultValue === false) {
    // eslint-disable-next-line @typescript-eslint/consistent-type-assertions
    return true;
  }

  // If Statsig is not initialized, return the default.
  if (!FeatureGates.initializeCompleted()) {
    // eslint-disable-next-line @typescript-eslint/consistent-type-assertions
    return defaultValue;
  }

  // Live Statsig value.
  // eslint-disable-next-line @atlaskit/platform/use-recommended-utils
  var value = FeatureGates.getExperimentValue(experimentName, param, defaultValue, {
    fireExperimentExposure: fireExperimentExposure
  });
  addFeatureFlagAccessed("".concat(experimentName, ":").concat(param), value);

  // eslint-disable-next-line @typescript-eslint/consistent-type-assertions
  return value;
}